// Krimble 2026-11-08: the symbols of the Color panel, cut out of the Picker mockup itself (George: "Is it that hard to copy these elements?") as white shapes on a transparent
// background, each cropped to the shape; the sizes are the mockup's own pixels (the card is 1178 px wide). Made with the brightness of each symbol as its transparency.
#pragma once
#include <QByteArray>
#include <QHash>
#include <QPixmap>
#include <QString>

inline QPixmap krimbleStudioSymbol(const QString &name)
{
    static QHash<QString, QPixmap> cache;
    auto found = cache.constFind(name);
    if (found != cache.constEnd()) return found.value();
    static const struct { const char *name; const char *data; } symbols[] = {
        { "eyedropper", "" },   // 45 x 46
        { "copy", "" },   // 37 x 39
        { "swap", "" },   // 44 x 41
        { "plus", "" },   // 40 x 40
        { "trash", "" },   // 38 x 43
        { "grid", "" },   // 39 x 39
        { "spin_up", "" },   // 18 x 11
        { "chev_drop", "" },   // 23 x 15
        { "spin_down", "" },   // 18 x 11
        { "pencil", "" },   // 44 x 44
        { "duplicate", "" },   // 43 x 44
        { "more", "" },   // 37 x 9
        { "chev_palette", "" },   // 24 x 15
        { "chev_recent", "" },   // 20 x 33
    };
    QPixmap pixmap;
    for (const auto &symbol : symbols) {
        if (name == QLatin1String(symbol.name)) { pixmap.loadFromData(QByteArray::fromBase64(QByteArray(symbol.data)), "PNG"); break; }
    }
    cache.insert(name, pixmap);
    return pixmap;
}
